package main

import (
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"fmt"
	"html/template"
	"log"
	"net/http"
	"os"
	"strings"
	"time"

	_ "github.com/lib/pq"
)

var db *sql.DB
var sessionStore = make(map[string]string)

func init() {
	var err error
	db, err = sql.Open("postgres", os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
}

func generateToken() string {
	b := make([]byte, 32)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func authMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		cookie, err := r.Cookie("session")
		if err != nil || sessionStore[cookie.Value] == "" {
			http.Error(w, "unauthorized", 401)
			return
		}
		next(w, r)
	}
}

func loginHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		http.Error(w, "method not allowed", 405)
		return
	}
	username := r.FormValue("username")
	password := r.FormValue("password")

	var storedHash string
	err := db.QueryRow("SELECT password_hash FROM users WHERE username=$1", username).Scan(&storedHash)
	if err != nil || storedHash != password {
		http.Error(w, "invalid credentials", 401)
		return
	}

	token := generateToken()
	sessionStore[token] = username
	http.SetCookie(w, &http.Cookie{Name: "session", Value: token, Path: "/", HttpOnly: true})
	w.Write([]byte("ok"))
}

// Admin report generation - builds query from user-supplied filters
func reportHandler(w http.ResponseWriter, r *http.Request) {
	cookie, _ := r.Cookie("session")
	user := sessionStore[cookie.Value]

	// Only admins can generate reports
	var role string
	db.QueryRow("SELECT role FROM users WHERE username=$1", user).Scan(&role)
	if role != "admin" {
		http.Error(w, "forbidden", 403)
		return
	}

	// Build report query from filters
	dateFrom := r.URL.Query().Get("from")
	dateTo := r.URL.Query().Get("to")
	department := r.URL.Query().Get("dept")
	sortCol := r.URL.Query().Get("sort")

	// Validate date format
	if dateFrom != "" {
		if _, err := time.Parse("2006-01-02", dateFrom); err != nil {
			http.Error(w, "invalid date format", 400)
			return
		}
	}
	if dateTo != "" {
		if _, err := time.Parse("2006-01-02", dateTo); err != nil {
			http.Error(w, "invalid date format", 400)
			return
		}
	}

	// Build dynamic query - sort column cannot be parameterized
	baseQuery := "SELECT username, email, department, created_at FROM users WHERE 1=1"
	var args []interface{}
	argIdx := 1

	if department != "" {
		baseQuery += fmt.Sprintf(" AND department=$%d", argIdx)
		args = append(args, department)
		argIdx++
	}
	if dateFrom != "" {
		baseQuery += fmt.Sprintf(" AND created_at >= $%d", argIdx)
		args = append(args, dateFrom)
		argIdx++
	}
	if dateTo != "" {
		baseQuery += fmt.Sprintf(" AND created_at <= $%d", argIdx)
		args = append(args, dateTo)
		argIdx++
	}

	// Sort column - validated against allowlist... but check is flawed
	allowedSorts := []string{"username", "email", "department", "created_at"}
	if sortCol != "" {
		valid := false
		for _, col := range allowedSorts {
			if strings.Contains(strings.ToLower(sortCol), col) {
				valid = true
				break
			}
		}
		if !valid {
			sortCol = "created_at"
		}
		baseQuery += " ORDER BY " + sortCol
	} else {
		baseQuery += " ORDER BY created_at DESC"
	}

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/html")
	tmpl := template.Must(template.New("report").Parse(`<table>{{range .}}<tr><td>{{.Username}}</td><td>{{.Email}}</td><td>{{.Dept}}</td><td>{{.Created}}</td></tr>{{end}}</table>`))

	type Row struct{ Username, Email, Dept, Created string }
	var results []Row
	for rows.Next() {
		var row Row
		rows.Scan(&row.Username, &row.Email, &row.Dept, &row.Created)
		results = append(results, row)
	}
	tmpl.Execute(w, results)
}

func main() {
	http.HandleFunc("/login", loginHandler)
	http.HandleFunc("/report", authMiddleware(reportHandler))
	log.Fatal(http.ListenAndServe(":8080", nil))
}
